    op.execute("""
        CREATE FUNCTION enforce_warehouse_capacity() RETURNS trigger AS $$
        DECLARE
            target_warehouse_id integer;
            target_capacity numeric;
            used_capacity numeric;
            item_capacity numeric;
        BEGIN
            IF TG_TABLE_NAME = 'warehouses' THEN
                target_warehouse_id := NEW.id;
                target_capacity := NEW.storage_capacity;
                SELECT COALESCE(SUM(i.quantity_on_hand * p.storage_units_per_item), 0)
                  INTO used_capacity
                  FROM inventories AS i
                  JOIN products AS p ON p.id = i.product_id
                 WHERE i.warehouse_id = target_warehouse_id;
            ELSIF TG_TABLE_NAME = 'products' THEN
                IF NEW.storage_units_per_item IS DISTINCT FROM OLD.storage_units_per_item
                   AND EXISTS (SELECT 1 FROM inventories WHERE product_id = OLD.id) THEN
                    RAISE EXCEPTION 'cannot change product storage units while inventory records exist'
                        USING ERRCODE = '23514', CONSTRAINT = 'ck_product_storage_units_immutable_when_stocked';
                END IF;
                RETURN NEW;
            ELSE
                target_warehouse_id := NEW.warehouse_id;
                IF target_warehouse_id IS NULL THEN
                    RETURN NEW;
                END IF;

                SELECT storage_capacity INTO target_capacity
                  FROM warehouses WHERE id = target_warehouse_id FOR UPDATE;
                SELECT storage_units_per_item INTO item_capacity
                  FROM products WHERE id = NEW.product_id FOR UPDATE;
                SELECT COALESCE(SUM(i.quantity_on_hand * p.storage_units_per_item), 0)
                  INTO used_capacity
                  FROM inventories AS i
                  JOIN products AS p ON p.id = i.product_id
                 WHERE i.warehouse_id = target_warehouse_id
                   AND i.id IS DISTINCT FROM NEW.id;
                used_capacity := used_capacity + NEW.quantity_on_hand * item_capacity;
            END IF;

            IF used_capacity > target_capacity THEN
                RAISE EXCEPTION 'warehouse capacity exceeded for warehouse %', target_warehouse_id
                    USING ERRCODE = '23514', CONSTRAINT = 'ck_warehouse_aggregate_capacity';
            END IF;
            RETURN NEW;
        END;
        $$ LANGUAGE plpgsql;
    """)
